// ============================================================
// GoogleCallback.js — Página de callback do Google OAuth
// Rota: /auth/google/callback
// O backend redireciona para cá após autenticação Google
// com ?token=JWT&user=JSON_encoded na URL
// ============================================================
import React, { useEffect, useContext, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import '../styles/Auth.css';

const GoogleCallback = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { login } = useContext(AuthContext);
  const [status, setStatus] = useState('Autenticando com Google...');
  const [error, setError] = useState('');

  useEffect(() => {
    const token = searchParams.get('token');
    const userParam = searchParams.get('user');
    const errorParam = searchParams.get('error');

    if (errorParam) {
      setError('Falha na autenticação com Google. Tente novamente.');
      setTimeout(() => navigate('/login'), 3000);
      return;
    }

    if (!token) {
      setError('Token não encontrado. Redirecionando...');
      setTimeout(() => navigate('/login'), 2000);
      return;
    }

    try {
      const user = userParam ? JSON.parse(decodeURIComponent(userParam)) : null;
      setStatus('Login realizado! Redirecionando...');
      login(token, user);
      setTimeout(() => navigate('/feed'), 1000);
    } catch (err) {
      console.error('Erro ao processar callback Google:', err);
      setError('Erro ao processar login. Tente novamente.');
      setTimeout(() => navigate('/login'), 2000);
    }
  }, [searchParams, login, navigate]);

  return (
    <div className="auth-page">
      <div className="auth-card" style={{ textAlign: 'center' }}>
        <div className="auth-logo">
          <span className="logo-text">Desafio<span className="logo-plus">+</span></span>
        </div>

        {error ? (
          <>
            <div className="alert alert-error">❌ {error}</div>
            <p className="auth-subtitle">Redirecionando para o login...</p>
          </>
        ) : (
          <>
            <div className="google-loading">
              <div className="spinner-large" />
            </div>
            <p className="auth-subtitle">{status}</p>
          </>
        )}
      </div>
    </div>
  );
};

export default GoogleCallback;
